interface Product {
  id: number;
  name: string;
  price: number;
  stockCount: number;
}

const db = new DatabaseSync('products.db');

function createTable(): void {
  db.exec(
    `CREATE TABLE IF NOT EXISTS products (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      price REAL NOT NULL,
      stockCount INTEGER NOT NULL
    )`
  );
}

function insertProduct(name: string, price: number, stockCount: number): number {
  const stmt = db.prepare(
    'INSERT INTO products (name, price, stockCount) VALUES (?, ?, ?)' as const
  );
  return stmt.run(name, price, stockCount).lastInsertRowid as number;
}

function getProductById(id: number): Product | null {
  const stmt = db.prepare(
    'SELECT * FROM products WHERE id = ?' as const
  );
  return stmt.get(id) as unknown as Product | null;
}

function getProducts(): Product[] {
  const stmt = db.prepare('SELECT * FROM products' as const);
  return stmt.all() as unknown as Product[];
}

function updateProduct(id: number, name: string, price: number, stockCount: number): boolean {
  const stmt = db.prepare(
    'UPDATE products SET name = ?, price = ?, stockCount = ? WHERE id = ?' as const
  );
  return stmt.run(name, price, stockCount, id).changes > 0;
}

function deleteProduct(id: number): boolean {
  const stmt = db.prepare('DELETE FROM products WHERE id = ?' as const);
  return stmt.run(id).changes > 0;
}

export { db, createTable, insertProduct, getProductById, getProducts, updateProduct, deleteProduct };

