function updateEvent(id: number, event: { name?: string; description?: string; date?: string; location?: string; total_tickets?: number }): boolean {
  const setClause: string[] = [];
  const params: any[] = [];

  if (event.name !== undefined) {
    setClause.push('name = ?');
    params.push(event.name);
  }

  if (event.description !== undefined) {
    setClause.push('description = ?');
    params.push(event.description);
  }

  if (event.date !== undefined) {
    setClause.push('date = ?');
    params.push(event.date);
  }

  if (event.location !== undefined) {
    setClause.push('location = ?');
    params.push(event.location);
  }

  if (event.total_tickets !== undefined) {
    setClause.push('total_tickets = ?');
    params.push(event.total_tickets);
  }

  if (setClause.length === 0) {
    return false;
  }

  const sql = `UPDATE events SET ${setClause.join(', ')} WHERE id = ?`;
  params.push(id);

  const result = db.prepare(sql).run(...params);
  return result.changes > 0;
